{
  "items": [
    {
      "fact_text": {
        "text": "The Math.round method returns a long value, so assigning its result directly to an int variable causes a compilation error because implicit casting from long to int is not allowed.",
        "refs": ["Q0000"],
        "claims": [
          {
            "text": "Math.round returns a long value.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0000"],
            "related_refs": []
          },
          {
            "text": "Assigning a long to an int variable without explicit casting causes a compilation error.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0000"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Explicit casting can be used to convert the long result of Math.round to an int when the programmer knows the value fits in 4 bytes.",
        "refs": ["Q0000"],
        "claims": [
          {
            "text": "Explicit casting can convert a long to an int when the value fits in the smaller type.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "corrected_approach",
            "refs": ["Q0000"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The result of the expression Math.random() * 100 is a number between 0 and 100.",
        "refs": ["Q0001"],
        "claims": [
          {
            "text": "Math.random() * 100 yields a number in the range 0 to 100.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0001"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Since the value is between 0 and 100, it can be stored in an integer variable.",
        "refs": ["Q0002"],
        "claims": [
          {
            "text": "A number between 0 and 100 fits within the range of an int.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0002"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Adding an int cast to the expression and running the program produces a valid integer result.",
        "refs": ["Q0003"],
        "claims": [
          {
            "text": "Adding an int cast and executing yields a valid integer output.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0003"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If the round method is omitted, the program will use the raw double value from Math.random() * 100.",
        "refs": ["Q0004"],
        "claims": [
          {
            "text": "Removing Math.round leaves a double result from Math.random() * 100.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "continuation",
            "refs": ["Q0004"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Casting the double result directly (without rounding) to int truncates the fractional part.",
        "refs": ["Q0005"],
        "claims": [
          {
            "text": "Casting a double to int truncates the fraction.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "alternative_valid_approach",
            "refs": ["Q0005"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Running the program after removing round and applying casting shows the integer result of the truncated double.",
        "refs": ["Q0006"],
        "claims": [
          {
            "text": "The program outputs the integer obtained by casting the double result.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0006"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    }
  ],
